project_cards=''.join(f'<article><h3>{escape(name)}</h3><p>{escape(desc)}</p><div class="actions"><a class="inline-link" href="{url}">Explore project ↗</a>'+ (f'<a href="{repo}">Repository</a>' if repo else '')+'</div></article>' for name,desc,url,repo in projects)
add('connections.html','Connected projects','Explore the projects and practical contributions named in the JRA Product Engine plan.',head('A network of possibilities.<br>Connected through work.','A song can become part of a collection. A garden can supply an ingredient. A club can bring people together around a useful product.')+f'''<section class="section"><div class="wrap"><div class="split"><div><h2>A connection begins<br>with an exchange.</h2><p>Name what is contributed, where it comes from, who is involved and the terms of use. A project retains its own purpose and can connect to several activities at once.</p></div><div class="note"><h3>Explore, then agree.</h3><p>These are reference connections from the plan. They do not establish partnerships, grant artwork rights or confirm anyone’s participation.</p></div></div></div></section><section class="section tint"><div class="wrap link-list">{project_cards}</div></section><section class="section"><div class="wrap split"><div><h2>More ways in.</h2><p>Garden Mate, Kitchen Mate, Fermentation Mate and Event Mate connect growing, preparation, preservation and gathering. Civic AI and local computing projects offer potential tools and services.</p><p>The plan names these families without a direct public link. A practical connection still needs a specific contribution and agreement.</p></div><div><h2>Ownership stays<br>with the agreement.</h2><p>Independent makers, businesses, cooperatives, joint projects and mutuals can participate. A mutual is one option for shared purchasing or productive assets, chosen by its members.</p><p>Membership and decision arrangements belong to that enterprise. They do not become rules for everyone using the engine.</p></div></div><div class="wrap">{source('chapters 8, 9, 12 and 14')}</div></section>''')

add('circular-use.html','Circular use','Follow care, repair, refill and material recovery through actual quantities, receiving routes and costs.',head('The next use<br>starts with this design.','Build care and continued use into the product from the beginning. Follow what actually returns, who receives it and what happens next.')+'''<img class="full-photo" src="assets/circular-use.png" alt="Imagined coastal workshop where people repair purple textiles and prepare reusable containers" width="1536" height="1024" loading="lazy"><div class="hero-caption">AI-generated concept artwork. Repair and refill as everyday activity.</div><section class="section"><div class="wrap"><div class="section-head"><h2>Keep the useful<br>parts moving.</h2><p>A circular route has practical requirements. Naming a material “recyclable” does not establish a working route.</p></div><div class="cards"><article class="card"><span class="number">01</span><h3>Design for use</h3><p>Consider durability, accurate sizing, care, replaceable parts and repair. Keep material composition with the specification.</p></article><article class="card"><span class="number">02</span><h3>Arrange the return</h3><p>Name a receiving point, acceptance conditions, transport, inspection and processing. Agree who does the work and how it is paid.</p></article><article class="card"><span class="number">03</span><h3>Record the result</h3><p>Track quantities, rejected items, losses, processing cost and the completed next use. Bring the learning back to design.</p></article></div></div></section><section class="section green"><div class="wrap split"><div><h2>Different products.<br>Different routes.</h2><p>A reusable drink container needs an agreed cleaning and refilling process. An outer garment may suit repair or resale. Worn underwear needs a suitable textile pathway with clear receiving conditions.</p></div><div><p>Offcuts, unused packaging, surplus stock and spare equipment capacity can become offers to others. Condition, quantity, transport and processing determine whether an exchange is practical.</p><p>Follow material movement separately from income movement. Both matter, and neither is a substitute for the other.</p></div></div></section><section class="section"><div class="wrap split"><div><h2>Measure the cycle<br>you actually have.</h2><p>The workbench compares quantities sent and received in the same unit. It also keeps the receiving conditions and actual result beside those numbers.</p><p>A return rate describes a movement. It does not prove a repair, a refill or an environmental benefit.</p><a class="btn" href="workbench.html">Record your next-use route ↗</a></div><div class="card"><h3>Keep the whole cost visible.</h3><p>Collection, cleaning, breakage, rejected items, labour and transport are part of the route. A useful circular model includes the work needed to sustain it.</p></div></div></section>'''+f'<div class="wrap">{source("chapters 4 to 8 and 13")}</div>')

add('media.html','Media and AI handoffs','Prepare connected creative releases and bounded agent tasks while people decide the story and commitments.',head('Let tools carry the admin.<br>Keep people in the story.','AI can help prepare briefs, comparisons and release material. People choose the creative direction and the commitments they make.')+'''<section class="section"><div class="wrap"><div class="split"><div><h2>A clear task.<br>A concrete result.</h2><p>Give an agent the intended result, source records, allowed actions, spending or publication limits and a person to contact for exceptions.</p><p>Existing permissions carry forward inside their agreed scope. A changed task or exception returns to the relevant person. Permissions can be paused or revoked.</p></div><div class="card"><h3>A compact handoff</h3><p>Record reference and version.</p><p>Work completed and next task.</p><p>Unresolved questions.</p><p>Permitted actions and limits.</p><p>The human decision and verified result.</p></div></div></div></section><section class="section tint"><div class="wrap"><div class="section-head"><h2>From a making story<br>to a media release.</h2><p>Use the product record to keep the words, images, specifications and credits consistent.</p></div><div class="steps"><article class="step"><span>01</span><div><h3>Collect and organise</h3><p>Bring footage, sound, music, artwork and the brief into one package. Keep source, context, permitted use and destinations attached.</p></div></article><article class="step"><span>02</span><div><h3>Assemble and shape</h3><p>Prepare selections, an edit map, captions and output layouts. Choose the asset bundle for Aura, P4A, GAJRA Earth or the participating club. Review a style frame before applying it across a batch.</p></div></article><article class="step"><span>03</span><div><h3>Check and deliver</h3><p>Review captions against the recording and watch the complete export. Supply filenames, credits, descriptions and permissions for each agreed destination.</p></div></article></div></div></section><section class="section"><div class="wrap split"><div><h2>Useful now.<br>Ready to connect later.</h2><p>The workbench creates an editable task brief and a release pack from your product record. It records permission status, but does not execute the task.</p><a class="btn" href="workbench.html">Prepare a handoff ↗</a></div><div><p>The plan describes Astra MCP as a proposed DaVinci Resolve control bridge. Its supported controls must be confirmed on the editing computer with a disposable project before use.</p><p>Links to the Screen & Media Network provide context. They do not presume a running venue or an agreed broadcast slot.</p><p><a class="inline-link" href="https://auraofintelligence.github.io/davinci-resolve-automations/how-it-works.html">Explore the Resolve workflow ↗</a></p></div></div></section>'''+f'<div class="wrap">{source("chapters 10, 15, 16 and 17")}</div>')

